internal static class Phase30FinalOracleContracts
{
    internal static void AssertExactMutationSurface()
    {
        var actual = DiscoverMutationSurface();
        actual.Select(Serialize).Should().Equal(CurrentProductionMutationActions,
            "every effective production non-read MVC action is a reviewed closed-surface contract; copy the failure output only after reviewing the changed route/signature/dependencies");
    }

    internal static void AssertExactLifecycleRegistrationsAndCapabilities()
    {
        using var sqlite = new SqliteConnection("Data Source=:memory:");
        sqlite.Open();
        var configuration = new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string, string?>()).Build();
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddBackendServicesCore(configuration, options => options.UseSqlite(sqlite));

        var descriptors = services.Select((descriptor, index) => Describe(descriptor, index)).ToArray();
        descriptors.Where(x => x.ServiceType == Full(typeof(ILifecycleOutboxProcessor)))
            .Select(x => x.Contract).Should().Equal($"{Full(typeof(ILifecycleOutboxProcessor))}|Scoped|type:{Full(typeof(LifecycleOutboxProcessor))}");
        descriptors.Where(x => x.ServiceType == Full(typeof(ILifecycleOutboxConsumer)))
            .Select(x => x.Contract).Should().Equal($"{Full(typeof(ILifecycleOutboxConsumer))}|Scoped|type:{Full(typeof(LifecyclePayloadValidationConsumer))}");

        using var provider = services.BuildServiceProvider(new ServiceProviderOptions { ValidateScopes = true, ValidateOnBuild = false });
        using var scope = provider.CreateScope();
        scope.ServiceProvider.GetRequiredService<ILifecycleOutboxProcessor>().Should().BeOfType<LifecycleOutboxProcessor>();
        scope.ServiceProvider.GetServices<ILifecycleOutboxConsumer>().Select(x => x.GetType()).Should().Equal(typeof(LifecyclePayloadValidationConsumer));
        var hosted = provider.GetServices<IHostedService>().Select(x => x.GetType()).ToArray();
        hosted.Should().Equal(typeof(LifecycleOutboxWorker));
        descriptors.Where(x => x.ServiceType == Full(typeof(IHostedService))).Select(x => x.Contract)
            .Should().Equal($"{Full(typeof(IHostedService))}|Singleton|type:{Full(typeof(LifecycleOutboxWorker))}");

        AssertConstructors(typeof(LifecycleOutboxProcessor),
            Full(typeof(IpcManagementContext)),
            $"System.Collections.Generic.IEnumerable`1[{Full(typeof(ILifecycleOutboxConsumer))}]",
            "Microsoft.Extensions.Options.IOptions`1[IPCManagement.Api.Infrastructure.LifecycleOutbox.LifecycleOutboxOptions]",
            Full(typeof(TimeProvider)),
            "Microsoft.Extensions.Logging.ILogger`1[IPCManagement.Api.Infrastructure.LifecycleOutbox.LifecycleOutboxProcessor]");
        AssertConstructors(typeof(LifecycleOutboxWorker),
            Full(typeof(IServiceScopeFactory)),
            "Microsoft.Extensions.Options.IOptions`1[IPCManagement.Api.Infrastructure.LifecycleOutbox.LifecycleOutboxOptions]",
            "Microsoft.Extensions.Logging.ILogger`1[IPCManagement.Api.Infrastructure.LifecycleOutbox.LifecycleOutboxWorker]");
        AssertConstructors(typeof(LifecyclePayloadValidationConsumer));

        AssertExactCapabilitySurface();
        AssertDeliveryOnlyIlClosure(typeof(LifecycleOutboxProcessor), typeof(LifecycleOutboxWorker), typeof(LifecyclePayloadValidationConsumer));
    }

    private static MutationActionContract[] DiscoverMutationSurface()
    {
        var builder = new WebHostBuilder().Configure(_ => { }).ConfigureServices(services =>
            services.AddControllers().AddApplicationPart(typeof(IPCManagement.Api.DependencyInjection).Assembly));
        using var server = new TestServer(builder);
        var provider = server.Services.GetRequiredService<IActionDescriptorCollectionProvider>();
        var actions = provider.ActionDescriptors.Items.OfType<ControllerActionDescriptor>()
            .Where(action =>
            {
                var methods = action.ActionConstraints?.OfType<HttpMethodActionConstraint>().SelectMany(x => x.HttpMethods).ToArray();
                return methods is null || methods.Length == 0 || methods.Any(method => method is not ("GET" or "HEAD" or "OPTIONS"));
            })
            .Select(action => new MutationActionContract(
                Full(action.ControllerTypeInfo.AsType()), action.ActionName,
                (action.ActionConstraints?.OfType<HttpMethodActionConstraint>().SelectMany(x => x.HttpMethods).Distinct(StringComparer.Ordinal).OrderBy(x => x, StringComparer.Ordinal).ToArray()) ?? [],
                action.AttributeRouteInfo?.Template ?? "<conventional>", Signature(action.MethodInfo),
                action.ControllerTypeInfo.DeclaredConstructors.Where(x => x.IsPublic).Select(x => x.GetParameters().Select(ParameterContract).ToArray()).OrderBy(x => string.Join("|", x), StringComparer.Ordinal).ToArray(),
                action.Parameters.OfType<ControllerParameterDescriptor>().Where(x => x.BindingInfo?.BindingSource == BindingSource.Services || x.ParameterInfo.GetCustomAttributes().Any(a => a.GetType().Name.Contains("FromKeyedServices", StringComparison.Ordinal)))
                    .Select(x => ParameterContract(x.ParameterInfo)).OrderBy(x => x, StringComparer.Ordinal).ToArray()))
            .OrderBy(x => x.ControllerFullName, StringComparer.Ordinal).ThenBy(x => x.ActionName, StringComparer.Ordinal)
            .ThenBy(x => x.EffectiveRoute, StringComparer.Ordinal).ThenBy(x => string.Join(",", x.HttpMethods), StringComparer.Ordinal).ThenBy(x => x.MethodSignature, StringComparer.Ordinal).ToArray();
        actions.GroupBy(x => $"{x.ControllerFullName}|{x.ActionName}|{string.Join(',', x.HttpMethods)}|{x.EffectiveRoute}|{x.MethodSignature}", StringComparer.Ordinal)
            .Should().OnlyContain(x => x.Count() == 1, "canonical MVC mutation keys must be unique");
        return actions;
    }

    private static DescriptorContract Describe(ServiceDescriptor descriptor, int index)
    {
        var serviceType = Full(descriptor.ServiceType);
        var shape = descriptor.ImplementationType is not null ? "type" : descriptor.ImplementationInstance is not null ? "instance" : "factory";
        var implementation = descriptor.ImplementationType is not null ? Full(descriptor.ImplementationType)
            : descriptor.ImplementationInstance is not null ? Full(descriptor.ImplementationInstance.GetType()) : "<realized-in-scope>";
        return new(serviceType, shape, $"{serviceType}|{descriptor.Lifetime}|{shape}:{implementation}");
    }

    private static void AssertConstructors(Type type, params string[] expected)
    {
        type.GetConstructors(BindingFlags.Public | BindingFlags.Instance).Should().ContainSingle().Which.GetParameters()
            .Select(x => Full(x.ParameterType)).Should().Equal(expected);
    }

