    {
        Surface(typeof(ILifecycleOutboxProcessor)).Should().Equal(
            "method:public:System.Threading.Tasks.Task`1[System.Int32] IPCManagement.Api.Infrastructure.LifecycleOutbox.ILifecycleOutboxProcessor.ProcessBatchAsync`0(System.Threading.CancellationToken cancellationToken)");
        Surface(typeof(ILifecycleOutboxConsumer)).Should().Equal(
            "method:public:System.Threading.Tasks.Task IPCManagement.Api.Infrastructure.LifecycleOutbox.ILifecycleOutboxConsumer.ConsumeAsync`0(IPCManagement.Api.Models.Entities.LifecycleOutboxMessage message,System.Threading.CancellationToken cancellationToken)",
            "property:public:System.String ConsumerName{get}");
        Surface(typeof(LifecyclePayloadValidationConsumer)).Should().Equal(
            "interface:IPCManagement.Api.Infrastructure.LifecycleOutbox.ILifecycleOutboxConsumer",
            "method:public:System.Threading.Tasks.Task IPCManagement.Api.Infrastructure.LifecycleOutbox.LifecyclePayloadValidationConsumer.ConsumeAsync`0(IPCManagement.Api.Models.Entities.LifecycleOutboxMessage message,System.Threading.CancellationToken cancellationToken)",
            "property:public:System.String ConsumerName{get}");
    }

    private static string[] Surface(Type type) => type.GetInterfaces().Where(x => x.Assembly == type.Assembly).Select(x => $"interface:{Full(x)}")
        .Concat(type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(x => !x.IsSpecialName).Select(x => $"method:public:{Signature(x)}"))
        .Concat(type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Select(x => $"property:public:{Full(x.PropertyType)} {x.Name}{{{(x.GetMethod is null ? "" : "get")}{(x.SetMethod is null ? "" : ";set")}}}"))
        .OrderBy(x => x, StringComparer.Ordinal).ToArray();

    private static void AssertDeliveryOnlyIlClosure(params Type[] roots)
    {
        var production = typeof(IPCManagement.Api.DependencyInjection).Assembly;
        var forbidden = new[] { "MaterialRequest", "ReconciliationBatch", "DbSet`1[IPCManagement.Api.Models.Entities.Material", "DbSet`1[IPCManagement.Api.Models.Entities.Reconciliation", "ExecuteSql", "FromSql", "System.Reflection", "System.Delegate" };
        var queue = new Queue<MethodBase>(roots.SelectMany(AllMethods));
        var visited = new HashSet<MethodBase>();
        while (queue.TryDequeue(out var method))
        {
            if (!visited.Add(method)) continue;
            foreach (var member in ResolveIlMembers(method))
            {
                var identity = $"{member.DeclaringType?.FullName}.{member.Name}";
                identity.Should().NotContainAny(forbidden, $"the exact registered lifecycle IL closure at {method.DeclaringType?.FullName}.{method.Name} is limited to delivery state");
                if (member is MethodBase called && called.DeclaringType?.Assembly == production && IsOwnedByRoots(called.DeclaringType, roots)) queue.Enqueue(called);
            }
        }
    }

    private static bool IsOwnedByRoots(Type type, Type[] roots) => roots.Contains(type) || roots.Any(root => type.FullName?.StartsWith(root.FullName + "+", StringComparison.Ordinal) == true);
    private static IEnumerable<MethodBase> AllMethods(Type type) => type.GetMethods(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic).Cast<MethodBase>().Concat(type.GetConstructors(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic));

    private static IEnumerable<MemberInfo> ResolveIlMembers(MethodBase method)
    {
        var body = method.GetMethodBody();
        if (body is null) yield break;
        var bytes = body.GetILAsByteArray()!;
        for (var offset = 0; offset < bytes.Length;)
        {
            var op = bytes[offset++] == 0xfe ? MultiByte[bytes[offset++]] : SingleByte[bytes[offset - 1]];
            var size = OperandSize(op.OperandType, bytes, offset);
            if (op.OperandType is OperandType.InlineField or OperandType.InlineMethod or OperandType.InlineTok or OperandType.InlineType)
            {
                var token = BitConverter.ToInt32(bytes, offset);
                MemberInfo member;
                try { member = method.Module.ResolveMember(token, method.DeclaringType?.GetGenericArguments(), method is MethodInfo mi ? mi.GetGenericArguments() : null)!; }
                catch (Exception ex) { throw new InvalidOperationException($"Unresolved production IL token 0x{token:X8} in {method.DeclaringType?.FullName}.{method.Name}.", ex); }
                yield return member;
            }
            offset += size;
        }
    }

    private static int OperandSize(OperandType type, byte[] bytes, int offset) => type switch
    {
        OperandType.InlineNone => 0, OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar => 1,
        OperandType.InlineVar => 2, OperandType.InlineI or OperandType.InlineBrTarget or OperandType.InlineField or OperandType.InlineMethod or OperandType.InlineSig or OperandType.InlineString or OperandType.InlineTok or OperandType.InlineType or OperandType.ShortInlineR => 4,
        OperandType.InlineI8 or OperandType.InlineR => 8,
        OperandType.InlineSwitch => 4 + BitConverter.ToInt32(bytes, offset) * 4,
        _ => throw new InvalidOperationException($"Unsupported IL operand {type}.")
    };

    private static string Signature(MethodInfo method) => $"{Full(method.ReturnType)} {Full(method.DeclaringType!)}.{method.Name}`{method.GetGenericArguments().Length}({string.Join(',', method.GetParameters().Select(ParameterContract))})";
    private static string ParameterContract(ParameterInfo p) => $"{(p.ParameterType.IsByRef ? p.IsOut ? "out " : p.IsIn ? "in " : "ref " : "")}{Full(p.ParameterType.IsByRef ? p.ParameterType.GetElementType()! : p.ParameterType)} {p.Name}{(Nullability.Create(p).ReadState == NullabilityState.Nullable ? "?" : "")}";
    private static string Full(Type type) => type.IsGenericType ? $"{type.GetGenericTypeDefinition().FullName![..^2]}`{type.GetGenericArguments().Length}[{string.Join(',', type.GetGenericArguments().Select(Full))}]" : type.FullName ?? type.Name;
    private static string Serialize(MutationActionContract x) => $"{x.ControllerFullName}|{x.ActionName}|{string.Join(',', x.HttpMethods)}|{x.EffectiveRoute}|{x.MethodSignature}|ctors={string.Join(';', x.PublicConstructorContracts.Select(c => string.Join(',', c)))}|injected={string.Join(',', x.ActionInjectedContracts)}";

    private static readonly NullabilityInfoContext Nullability = new();
    private static readonly OpCode[] SingleByte = BuildOpcodes(false);
    private static readonly OpCode[] MultiByte = BuildOpcodes(true);
    private static OpCode[] BuildOpcodes(bool multi)
    {
        var result = new OpCode[256];
        foreach (var field in typeof(OpCodes).GetFields(BindingFlags.Public | BindingFlags.Static))
        {
            var op = (OpCode)field.GetValue(null)!;
            if ((op.Size == 2) == multi) result[(byte)op.Value] = op;
        }
        return result;
    }

